 public void onCreate(Bundle b){super.onCreate(b);prefs=getSharedPreferences("workspace",0);getWindow().setStatusBarColor(0xfff1f5f8);getWindow().setNavigationBarColor(0xfff1f5f8);getWindow().getDecorView().setSystemUiVisibility(View.SYSTEM_UI_FLAG_LIGHT_STATUS_BAR|View.SYSTEM_UI_FLAG_LIGHT_NAVIGATION_BAR);LinearLayout root=new LinearLayout(this);root.setOrientation(1);root.setBackgroundColor(0xfff1f5f8);root.setOnApplyWindowInsetsListener((v,i)->{root.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(root);root.requestApplyInsets();TextView back=text("‹  桌面设置",18,ink);back.setPadding(dp(24),dp(16),dp(24),dp(16));back.setOnClickListener(v->finish());root.addView(back);scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setVerticalScrollBarEnabled(false);root.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));LinearLayout outer=new LinearLayout(this);outer.setGravity(Gravity.TOP|Gravity.CENTER_HORIZONTAL);scroll.addView(outer);content=new LinearLayout(this);content.setOrientation(1);content.setPadding(dp(20),dp(4),dp(20),dp(32));outer.addView(content,new LinearLayout.LayoutParams(Math.min(getResources().getDisplayMetrics().widthPixels,dp(640)),-2));}
 protected void onResume(){super.onResume();draw();}
 LinearLayout card(){LinearLayout card=new LinearLayout(this);card.setOrientation(1);card.setPadding(dp(16),dp(14),dp(16),dp(14));card.setBackground(bg(Color.WHITE,20));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.bottomMargin=dp(12);content.addView(card,lp);return card;}
 void section(String value){TextView t=text(value,13,muted);t.setTypeface(null,Typeface.BOLD);t.setPadding(dp(4),dp(18),0,dp(10));content.addView(t);}
